        private void SyncModernUi(bool force=false)
        {
            if(modernCanvas==null)return;Rect safe=Screen.safeArea;safeAreaRoot.anchorMin=new Vector2(safe.xMin/Screen.width,safe.yMin/Screen.height);safeAreaRoot.anchorMax=new Vector2(safe.xMax/Screen.width,safe.yMax/Screen.height);
            if(force||uiRenderedState!=state){uiRenderedState=state;menuScreen.SetActive(state==State.Menu);heroScreen.SetActive(state==State.HeroSelect);hudScreen.SetActive(state==State.Playing);upgradeScreen.SetActive(state==State.Upgrade);petScreen.SetActive(state==State.PetUnlock);pauseScreen.SetActive(state==State.Paused);endScreen.SetActive(state==State.Dead||state==State.Victory);if(state==State.Upgrade)RenderUpgradeCards();if(state==State.PetUnlock)RenderPetModal();if(state==State.Dead||state==State.Victory){endTitleText.text=state==State.Victory?"ЗАБЕГ ЗАВЕРШЁН":"ОПЕРАТИВНИК ПОГИБ";endStatsText.text="Уничтожено целей: "+kills;}}
            if(state!=State.Playing)return;heroNameText.text=hero.displayName;levelText.text="УРОВЕНЬ "+level;hpText.text="HP  "+Mathf.CeilToInt(hp)+" / "+Mathf.CeilToInt(maxHp);hpFill.fillAmount=maxHp>0?hp/maxHp:0;xpText.text="ОПЫТ  "+xp+" / "+xpNeed;xpFill.fillAmount=xpNeed>0?(float)xp/xpNeed:0;timerText.text=$"{(int)(runTime/60):00}:{(int)(runTime%60):00}";killsText.text="УНИЧТОЖЕНО: "+kills;
            var heroPortrait=hudScreen.transform.Find("HeroHUD/HeroContent/HeroPortrait")?.GetComponent<Image>();if(heroPortrait!=null)heroPortrait.sprite=TextureSprite(heroPortraits[(int)hero.kind]);petHudPortrait.gameObject.SetActive(petUnlocked);petHudPortrait.sprite=petUnlocked?TextureSprite(petPortrait):null;petHudText.text=petUnlocked?petDefinition.displayName:"ВКУСНЯШКИ\n"+treatsCollected+" / 3";
            bossRoot.gameObject.SetActive(currentBoss!=null);if(currentBoss!=null){bossNameText.text=currentBoss.boss.name;bossFill.fillAmount=currentBoss.maxHp>0?currentBoss.hp/currentBoss.maxHp:0;}
            bool showAbility=abilityFlashTimer>0;abilityNoticeRoot.gameObject.SetActive(showAbility);if(showAbility){abilityNoticeText.text=abilityFlash;abilityNoticeIcon.sprite=abilityFlashSlot>=0?TextureSprite(UiIcon(AbilityIconId(hero.kind,abilityFlashSlot))):null;}
            bool showJoystick=joystickFinger>=0;joystickBase.gameObject.SetActive(showJoystick);if(showJoystick){Vector2 screenPos=joystickOrigin;RectTransformUtility.ScreenPointToLocalPointInRectangle(safeAreaRoot,screenPos,modernCanvas.worldCamera,out Vector2 local);joystickBase.anchoredPosition=local;joystickKnob.anchoredPosition=Vector2.ClampMagnitude(moveInput,1)*42f;}
            if(force||uiRenderedLevel!=level||uiRenderedPetCount!=treatsCollected||uiRenderedBoss!=currentBoss){uiRenderedLevel=level;uiRenderedPetCount=treatsCollected;uiRenderedBoss=currentBoss;RenderLoadout();}
        }

