        public void DebugPreviewUi(string screen)
        {
            if(hero==null)SetHero(HeroKind.Amelia);
            if(screen=="Menu")state=State.Menu;else if(screen=="HeroSelect")state=State.HeroSelect;else if(screen=="HUD"){if(!player.activeSelf)StartRun();state=State.Playing;}else if(screen=="Upgrade"){RollUpgrades();state=State.Upgrade;}else if(screen=="Pet"){petDefinition=PetCatalog.ForOwner(hero.id);petPortrait=Resources.Load<Texture2D>(petDefinition.portraitResource);state=State.PetUnlock;}else if(screen=="Pause")state=State.Paused;else if(screen=="Boss"){if(!player.activeSelf)StartRun();if(currentBoss==null)SpawnBoss(BossKind.EarthDragon);state=State.Playing;}else if(screen=="End")state=State.Victory;SyncModernUi(true);
        }
        public string RunUiLayoutAudit()
        {
            if(modernCanvas==null)return "Canvas is not initialized";int issues=0,labels=0,buttons=0;var safe=safeAreaRoot.rect;
            foreach(var label in modernCanvas.GetComponentsInChildren<TMP_Text>(true)){labels++;if(!label.gameObject.activeInHierarchy)continue;label.ForceMeshUpdate();var rt=label.rectTransform;if(label.preferredWidth>rt.rect.width+1&&!label.enableWordWrapping){Debug.LogWarning("UI_AUDIT horizontal overflow: "+HierarchyPath(rt));issues++;}if(label.preferredHeight>rt.rect.height+1&&label.overflowMode!=TextOverflowModes.Ellipsis){Debug.LogWarning("UI_AUDIT vertical overflow: "+HierarchyPath(rt));issues++;}}
            foreach(var button in modernCanvas.GetComponentsInChildren<Button>(true)){buttons++;if(button.targetGraphic==null){Debug.LogWarning("UI_AUDIT button has no visual: "+HierarchyPath(button.transform));issues++;}}
            string result=$"UI AUDIT: {issues} issue(s), {labels} TMP labels, {buttons} buttons, SafeArea {safe.width:0}x{safe.height:0}";Debug.Log(result);return result;
        }
        private static string HierarchyPath(Transform value){string path=value.name;while(value.parent!=null){value=value.parent;path=value.name+"/"+path;}return path;}

        private GameObject ScreenRoot(string name,bool active,bool dim=false){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(safeAreaRoot,false);Stretch((RectTransform)go.transform,0,0,0,0);if(dim){var image=go.AddComponent<Image>();image.color=new Color(0,0,0,.72f);}go.SetActive(active);return go;}
        private void AddBackground(Transform parent){var raw=new GameObject("Background",typeof(RectTransform),typeof(RawImage)).GetComponent<RawImage>();raw.transform.SetParent(parent,false);Stretch(raw.rectTransform,0,0,0,0);raw.texture=uiMenuBackground;raw.uvRect=new Rect(0,0,1,1);raw.color=new Color(.78f,.82f,.86f,1);raw.raycastTarget=false;}
        private RectTransform Panel(string name,Transform parent,Vector2 size,Color? color=null){var rt=Rect(name,parent);rt.sizeDelta=size;var image=rt.gameObject.AddComponent<Image>();bool card=name.StartsWith("Character_")||name.StartsWith("UpgradeCard_");bool large=size.x>=600&&size.y>=400;image.sprite=card&&cardArtSprite!=null?cardArtSprite:large&&panelArtSprite!=null?panelArtSprite:panelSprite;image.type=(card&&cardArtSprite!=null)||(large&&panelArtSprite!=null)?Image.Type.Simple:Image.Type.Sliced;image.color=color??Color.white;return rt;}
        private Button PrimaryButton(Transform parent,string label,Action action,float width,float height){var rt=Rect("Button_"+label,parent);rt.sizeDelta=new Vector2(width,height);var image=rt.gameObject.AddComponent<Image>();image.sprite=buttonArtSprite!=null?buttonArtSprite:buttonSprite;image.type=buttonArtSprite!=null?Image.Type.Simple:Image.Type.Sliced;var button=rt.gameObject.AddComponent<Button>();var colors=button.colors;colors.normalColor=Color.white;colors.highlightedColor=new Color(1.12f,1.12f,1.12f);colors.pressedColor=new Color(.62f,.78f,.82f);colors.disabledColor=new Color(.25f,.3f,.32f,.7f);colors.fadeDuration=.08f;button.colors=colors;button.onClick.AddListener(()=>action());var text=Text("Label",rt,label,UiToken.Button,17,22,TextAlignmentOptions.Center);Stretch(text.rectTransform,34,34,10,10);text.enableWordWrapping=false;text.overflowMode=TextOverflowModes.Ellipsis;text.fontStyle=FontStyles.Bold;var le=rt.gameObject.AddComponent<LayoutElement>();le.preferredWidth=width;le.preferredHeight=height;le.minHeight=52;return button;}
        private RectTransform Vertical(string name,Transform parent,float padding,float spacing,TextAnchor align){var rt=Rect(name,parent);var layout=rt.gameObject.AddComponent<VerticalLayoutGroup>();layout.padding=new RectOffset((int)padding,(int)padding,(int)padding,(int)padding);layout.spacing=spacing;layout.childAlignment=align;layout.childControlWidth=true;layout.childControlHeight=false;layout.childForceExpandWidth=true;layout.childForceExpandHeight=false;return rt;}
        private RectTransform Horizontal(string name,Transform parent,float spacing,float padding,TextAnchor align){var rt=Rect(name,parent);var layout=rt.gameObject.AddComponent<HorizontalLayoutGroup>();layout.padding=new RectOffset((int)padding,(int)padding,(int)padding,(int)padding);layout.spacing=spacing;layout.childAlignment=align;layout.childControlWidth=false;layout.childControlHeight=false;layout.childForceExpandWidth=false;layout.childForceExpandHeight=false;return rt;}
        private TMP_Text LayoutText(Transform parent,string value,float size,float min,float max,float height,FontStyles style=FontStyles.Normal,Color? color=null,TextAlignmentOptions alignment=TextAlignmentOptions.Center){var text=Text("Text",parent,value,size,min,max,alignment);text.fontStyle=style;text.color=color??UiToken.Text;var le=text.gameObject.AddComponent<LayoutElement>();le.preferredHeight=height;le.minHeight=Mathf.Min(height,28);return text;}
        private TMP_Text Text(string name,Transform parent,string value,float size,float min,float max,TextAlignmentOptions alignment){var rt=Rect(name,parent);var text=rt.gameObject.AddComponent<TextMeshProUGUI>();text.font=modernFont;text.text=value;text.fontSize=size;text.enableAutoSizing=true;text.fontSizeMin=min;text.fontSizeMax=max;text.color=UiToken.Text;text.alignment=alignment;text.enableWordWrapping=true;text.overflowMode=TextOverflowModes.Ellipsis;text.raycastTarget=false;text.margin=new Vector4(2,2,2,2);return text;}
        private Image ImageNode(string name,Transform parent,Texture2D texture,bool preserve){var rt=Rect(name,parent);var image=rt.gameObject.AddComponent<Image>();image.sprite=TextureSprite(texture);image.preserveAspect=preserve;image.raycastTarget=false;return image;}
        private Image Bar(Transform parent,string name,Color fillColor,float width,float height){var bg=Rect(name,parent);bg.sizeDelta=new Vector2(width,height);bg.gameObject.AddComponent<LayoutElement>().preferredHeight=height;var image=bg.gameObject.AddComponent<Image>();image.sprite=barSprite;image.type=Image.Type.Sliced;image.color=Color.white;var fillRt=Rect("Fill",bg);Stretch(fillRt,3,3,3,3);var fill=fillRt.gameObject.AddComponent<Image>();fill.sprite=barSprite;fill.type=Image.Type.Filled;fill.fillMethod=Image.FillMethod.Horizontal;fill.color=fillColor;return fill;}
        private void Spacer(Transform parent,float height){var rt=Rect("Spacer",parent);rt.gameObject.AddComponent<LayoutElement>().preferredHeight=height;}
        private static RectTransform Rect(string name,Transform parent){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);return (RectTransform)go.transform;}
        private static void Stretch(RectTransform rt,float left,float right,float top,float bottom){rt.anchorMin=Vector2.zero;rt.anchorMax=Vector2.one;rt.offsetMin=new Vector2(left,bottom);rt.offsetMax=new Vector2(-right,-top);}
        private static void Anchor(RectTransform rt,Vector2 min,Vector2 max,Vector2 position){rt.anchorMin=min;rt.anchorMax=max;rt.pivot=(min+max)*.5f;rt.anchoredPosition=position;}
        private static void SetAnchored(RectTransform rt,Vector2 min,Vector2 max,Vector2 position,Vector2 size){rt.anchorMin=min;rt.anchorMax=max;rt.pivot=(min+max)*.5f;rt.anchoredPosition=position;rt.sizeDelta=size;}
        private static void Clear(Transform root){for(int i=root.childCount-1;i>=0;i--)Destroy(root.GetChild(i).gameObject);}
        private Sprite TextureSprite(Texture2D texture){if(texture==null)return null;return Sprite.Create(texture,new Rect(0,0,texture.width,texture.height),new Vector2(.5f,.5f),100);}
        private static Sprite CreateNineSlice(string name,Color center,Color edge){const int s=24,b=6;var texture=new Texture2D(s,s,TextureFormat.RGBA32,false){name=name,filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};var pixels=new Color[s*s];for(int y=0;y<s;y++)for(int x=0;x<s;x++){bool border=x<b||x>=s-b||y<b||y>=s-b;pixels[y*s+x]=border?edge:center;}texture.SetPixels(pixels);texture.Apply(false,true);return Sprite.Create(texture,new Rect(0,0,s,s),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,new Vector4(b,b,b,b));}
    }

    public sealed class SafeAreaLayout:MonoBehaviour
    {
        private Rect lastSafe;private Vector2Int lastScreen;
        private void Update(){if(lastSafe==Screen.safeArea&&lastScreen.x==Screen.width&&lastScreen.y==Screen.height)return;lastSafe=Screen.safeArea;lastScreen=new Vector2Int(Screen.width,Screen.height);var rt=(RectTransform)transform;rt.anchorMin=new Vector2(lastSafe.xMin/Screen.width,lastSafe.yMin/Screen.height);rt.anchorMax=new Vector2(lastSafe.xMax/Screen.width,lastSafe.yMax/Screen.height);rt.offsetMin=rt.offsetMax=Vector2.zero;}
    }
}
